    public function summary(Request $r) {
        $tenant=$this->tenant($r);$divisions=$this->divisionData($tenant);
        foreach($divisions as &$d){$teamIds=array_column($d['teams'],'id');$projects=DB::table('projects')->where('tenant_id',$tenant)->whereNull('deleted_at')->whereIn('team_id',$teamIds)->get();$d['active']=$projects->where('status','active')->count();$d['lagged']=0;$d['closed']=$projects->whereIn('status',['done','archived'])->count();$d['kpi_achievement']=$projects->count()?round($d['closed']/$projects->count()*100):0;$d['average_finish_days']=0.0;$d['active_projects']=$projects->whereIn('status',['active','planning','on_hold','review'])->map(function($p)use($tenant){$tasks=DB::table('tasks')->where('tenant_id',$tenant)->where('project_id',$p->id)->whereNull('deleted_at');return ['id'=>$p->id,'display_number'=>(int)$p->display_number,'name'=>$p->name,'status'=>$p->status,'open_tasks'=>(clone $tasks)->where('board_column','!=','done')->count(),'overdue_tasks'=>(clone $tasks)->where('board_column','!=','done')->where('due_date','<',now())->count()];})->values()->all();}
        return $this->ok($r,['tenant_name'=>DB::table('tenants')->where('id',$tenant)->value('name'),'teams'=>DB::table('teams')->where('tenant_id',$tenant)->count(),'users'=>DB::table('users')->where('tenant_id',$tenant)->count(),'projects'=>DB::table('projects')->where('tenant_id',$tenant)->whereNull('deleted_at')->count(),'open_tasks'=>DB::table('tasks')->where('tenant_id',$tenant)->whereNull('deleted_at')->where('board_column','!=','done')->count(),'divisions'=>$divisions]);
    }
    public function divisions(Request $r){return $this->ok($r,$this->divisionData($this->tenant($r)));}
