    public function addDivisionMembers(Request $r,string $id){if(!in_array($this->user($r)->role,['admin','manager']))return $this->fail($r,'FORBIDDEN','admin or manager role required',403);$d=$r->validate(['team_id'=>'required|uuid','member_ids'=>'required|array|min:1|max:100','member_ids.*'=>'uuid']);$team=DB::table('teams')->where('tenant_id',$this->tenant($r))->where('division_id',$id)->where('id',$d['team_id'])->first();if(!$team)return $this->fail($r,'VALIDATION_ERROR','selected team does not belong to this division',422,'team_id');$memberIds=array_values(array_unique($d['member_ids']));if(DB::table('users')->where('tenant_id',$this->tenant($r))->whereIn('id',$memberIds)->count()!==count($memberIds))return $this->fail($r,'VALIDATION_ERROR','one or more members do not belong to this workspace',422,'member_ids');DB::transaction(function()use($r,$id,$team,$memberIds){DB::table('users')->where('tenant_id',$this->tenant($r))->whereIn('id',$memberIds)->update(['team_id'=>$team->id,'updated_at'=>now()]);$this->audit($r,'add_members','division',$id,['team_id'=>$team->id,'member_ids'=>$memberIds]);});return $this->ok($r,['id'=>$id,'team_id'=>$team->id,'member_ids'=>$memberIds]);}
    public function setLeads(Request $r,string $id){if($this->user($r)->role!=='admin')return $this->fail($r,'FORBIDDEN','admin role required',403);$ids=$r->validate(['user_ids'=>'array','user_ids.*'=>'uuid'])['user_ids']??[];DB::transaction(function()use($r,$id,$ids){DB::table('division_leads')->where('tenant_id',$this->tenant($r))->where('division_id',$id)->delete();foreach(array_unique($ids) as $uid)DB::table('division_leads')->insert(['id'=>(string)Str::uuid(),'tenant_id'=>$this->tenant($r),'division_id'=>$id,'user_id'=>$uid,'created_at'=>now(),'updated_at'=>now()]);$this->audit($r,'assign_leads','division',$id,['lead_user_ids'=>$ids]);});return $this->ok($r,collect($this->divisionData($this->tenant($r)))->firstWhere('id',$id));}
