    public function deleteSimulation(Request $r){if($this->user($r)->role!=='admin')return $this->fail($r,'FORBIDDEN','admin role required',403);$batches=DB::table('simulation_batches')->where('tenant_id',$this->tenant($r))->where('status','active')->pluck('id');if($batches->isEmpty())return $this->ok($r,['deleted'=>false,'records'=>0]);$records=DB::table('simulation_records')->where('tenant_id',$this->tenant($r))->whereIn('batch_id',$batches)->get();DB::transaction(function()use($r,$batches,$records){foreach($records->groupBy('entity_type') as $type=>$items){$ids=$items->pluck('entity_id');if(in_array($type,['projects','tasks','wiki_pages','meeting_notes','decision_logs','lessons_learned','knowledge_workspaces']))DB::table($type)->where('tenant_id',$this->tenant($r))->whereIn('simulation_batch_id',$batches)->update(['deleted_at'=>now(),'updated_at'=>now()]);elseif($type==='checklist_items')DB::table($type)->where('tenant_id',$this->tenant($r))->whereIn('simulation_batch_id',$batches)->delete();}$grouped=$records->groupBy('entity_type');foreach(['users','teams','divisions'] as $entityType){$ids=($grouped->get($entityType)??collect())->pluck('entity_id');if($ids->isNotEmpty())DB::table($entityType)->where('tenant_id',$this->tenant($r))->whereIn('id',$ids)->delete();}DB::table('simulation_batches')->where('tenant_id',$this->tenant($r))->whereIn('id',$batches)->update(['status'=>'deleted','deleted_at'=>now(),'updated_at'=>now()]);foreach($batches as $batch)$this->audit($r,'delete','simulation_batch',$batch,['records'=>$records->where('batch_id',$batch)->count()]);});return $this->ok($r,['deleted'=>true,'records'=>$records->count()]);}}
